// commands.ts —— 键盘 / pad / 按钮条发来的命令 → 编辑器状态。created 2026-10-06 by Claude Opus 5.5；2026-10-07 UX-2 改
// 键盘怎么变成命令 = src/input/keys.ts（一张表）；这里只管命令做什么。
import type { Dir } from "./pitch.ts";
import { type EditorState, type Art, type Dyn, setDynSel, dynMarkSel, toggleSlurBefore, toggleWedgeBefore, writeDegree, writeRest, writeBar, writePhrase, shorter, longer, setTuplet, extend, tapAcc, octaveTarget, stepTarget, alterTarget, moveCaret, extendSelection, setCaret, escape, backspace, deleteForward, transposeSel, respellSel, modulateSel, selectToEdge, tr, toggleStaff, toggleArtBefore, setSelDur, scaleSelDur } from "./song.ts";

export type Command =
  | { k: "degree"; degree: number; dir: Dir }
  | { k: "rest" } | { k: "bar" } | { k: "phrase" } | { k: "art"; a: Art } | { k: "slur" } | { k: "wedge"; w: "cresc" | "dim" } | { k: "dyn"; v: Dyn }   // art = 光标前那个音（有选区 = 选中的）切演奏法（pad 符号层；前面不是音 = 原样）
  | { k: "shorter" } | { k: "longer" } | { k: "tuplet" } | { k: "extend"; half?: boolean }   // half = pad 的「/2」开着：拉长半份（= 附点）
  | { k: "acc"; acc: 1 | -1 }
  | { k: "octave"; d: number } | { k: "step"; d: number } | { k: "alter"; d: number }
  | { k: "caret"; d: number } | { k: "selext"; d: number } | { k: "home" } | { k: "end" } | { k: "escape" }
  | { k: "backspace" } | { k: "delete" }
  | { k: "transpose"; semis: number } | { k: "respell" } | { k: "seldur" } | { k: "selscale"; f: 0.5 | 2 } | { k: "modulate"; fifths: number } | { k: "seledge"; d: -1 | 1 }
  | { k: "staff" };   // 大谱表：这个音换到另一张谱表

/** 应用一条编辑命令。now = 判 Shift 连点用的时刻（ms）。 */
export function apply(st: EditorState, c: Command, now = Date.now()): EditorState {
  switch (c.k) {
    case "degree": return writeDegree(st, c.degree, c.dir);
    case "rest": return writeRest(st);
    case "bar": return writeBar(st);
    case "phrase": return writePhrase(st);
    case "art": return toggleArtBefore(st, c.a) ?? st;
    case "slur": return toggleSlurBefore(st) ?? st;
    case "wedge": return toggleWedgeBefore(st, c.w) ?? st;
    case "dyn": return setDynSel(st, dynMarkSel(st) === c.v ? null : c.v);   // 力度：光标处（有选区 = 选区开头）放这个记号，管到下一个；那儿已经是它 = 去掉   // 光标前那个音往下一个音渐强 / 渐弱（有选区 = 选区那样）   // 光标前那个音连到下一个（有选区 = 选区那样）
    case "shorter": return shorter(st);
    case "longer": return longer(st);
    case "tuplet": return setTuplet(st, st.input.tuplet ? 0 : 3);
    case "extend": return extend(st, !!c.half);
    case "acc": return tapAcc(st, c.acc, now);
    case "octave": return octaveTarget(st, c.d);
    case "step": return stepTarget(st, c.d);
    case "alter": return alterTarget(st, c.d);
    case "caret": return moveCaret(st, c.d);
    case "selext": return extendSelection(st, c.d);
    case "home": return setCaret(st, 0);   // setCaret 自己夹到谱头后面
    case "end": return setCaret(st, tr(st).length);
    case "staff": return toggleStaff(st, 2);
    case "escape": return escape(st);
    case "backspace": return backspace(st);
    case "delete": return deleteForward(st);
    case "transpose": return transposeSel(st, c.semis);
    case "respell": return respellSel(st);
    case "seldur": return setSelDur(st, st.input.unit);   // 选区菜单「都改成 ♪」= 长短旋钮现在那一档
    case "selscale": return scaleSelDur(st, c.f);          // 选区菜单「÷2 / ×2」
    case "modulate": return modulateSel(st, c.fifths);
    case "seledge": return selectToEdge(st, c.d);
  }
}
